(() => {
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, null);
  let node;
  while ((node = walker.nextNode())) {
    if (node.nodeValue && node.nodeValue.trim() === 'river-flash-7759') {
      const el = node.parentElement;
      const rect = el.getBoundingClientRect();
      return {
        tag: el.tagName,
        cls: el.className,
        text: el.textContent,
        x: rect.x, y: rect.y, w: rect.width, h: rect.height,
        selector: el.tagName.toLowerCase() + (el.id ? '#' + el.id : '') + (el.className ? '.' + String(el.className).trim().split(/\s+/).join('.') : '')
      };
    }
  }
  return null;
})()

(() => {
  const codes = document.querySelectorAll('code');
  return Array.from(codes).map(c => ({
    text: c.textContent,
    y: c.getBoundingClientRect().y
  }));
})()

(() => {
  const codes = document.querySelectorAll('code');
  return Array.from(codes).map((c, i) => {
    const parent = c.parentElement;
    const grand = parent.parentElement;
    return {
      i,
      text: c.textContent,
      parentTag: parent.tagName,
      parentCls: parent.className,
      grandTag: grand.tagName,
      grandCls: grand.className,
    };
  });
})()

(() => {
  const body = document.body;
  const sections = body.children;
  const info = [];
  for (const c of sections) {
    info.push({tag: c.tagName, cls: c.className, id: c.id});
  }
  // Test selector: section:nth-of-type(2) code
  let target = null;
  try {
    const candidates = body.querySelectorAll('section:nth-of-type(2) code');
    target = Array.from(candidates).map(c => c.textContent);
  } catch (e) {
    target = 'err: ' + e.message;
  }
  return {bodyChildren: info, selectorHits: target};
})()
